# Tidy Asset Allocation in R
# Chapter 9: Mean-Variance Optimization
# https://www.tidy-pm.com/dev/chapters/09-mean-variance.html
#
# The R code of the chapter, in the order it runs there.
# Run 00-setup.R once, then this file from the folder that holds it;
# generated by tools/build-code.py from the book's source.

## ---- setup ----
source("_common.R")
library(tidypm)
library(knitr)

## ---- data ----
R  <- as_xts_pm(sim_class_returns_monthly, date, class, return)
rf <- sim_riskfree_monthly$return
Re <- R - rf
stopifnot(ncol(Re) == 16L, !anyNA(Re))

# ===== Worked: two assets, by hand =====

## ---- two-asset-inputs ----
pair <- c("US_equity", "US_government")
X    <- Re[, pair]

s1  <- stats::sd(X[, 1]) * sqrt(12)          # equity volatility
s2  <- stats::sd(X[, 2]) * sqrt(12)          # government volatility
rho <- stats::cor(X)[1, 2]
s12 <- rho * s1 * s2

w1       <- (s2^2 - s12) / (s1^2 + s2^2 - 2 * s12)
port_vol <- sqrt(w1^2 * s1^2 + (1 - w1)^2 * s2^2 + 2 * w1 * (1 - w1) * s12)

round(c(sigma_equity = s1, sigma_government = s2,
        correlation = rho, covariance = s12), 4)

## ---- two-asset-weights ----
round(c(w_equity = w1, w_government = 1 - w1,
        portfolio_vol = port_vol,
        lowest_vol_constituent = min(s1, s2),
        discount = port_vol / min(s1, s2) - 1), 4)

## ---- two-asset-rho ----
vary_rho <- function(r) {
  cv <- r * s1 * s2
  w  <- (s2^2 - cv) / (s1^2 + s2^2 - 2 * cv)
  c(rho = r, w_equity = w,
    # at rho = -1 the variance is zero and floating point can return a tiny
    # negative number; the floor keeps the square root defined
    portfolio_vol = sqrt(pmax(0, w^2 * s1^2 + (1 - w)^2 * s2^2 + 2 * w * (1 - w) * cv)))
}

round(t(vapply(c(-1, -0.5, 0, rho, 0.5, 0.9, 1), vary_rho, numeric(3))), 4)

## ---- two-asset-check ----
S2   <- stats::cov(X) * 12
i2   <- rep(1, 2)
w_mx <- as.numeric(solve(S2) %*% i2) / as.numeric(t(i2) %*% solve(S2) %*% i2)

stopifnot(all.equal(w1, w_mx[1]))
round(c(by_hand = w1, by_matrix = w_mx[1]), 8)

# ===== Looking at the inputs first =====

## ---- moments ----
ann_ret <- function(x) prod(1 + x)^(12 / length(x)) - 1
ann_vol <- function(x) stats::sd(x) * sqrt(12)

moments <- tibble::tibble(
  asset = colnames(R),
  mean_arith = apply(R, 2, mean) * 12,
  mean_comp  = apply(R, 2, ann_ret),
  vol        = apply(R, 2, ann_vol)
) |>
  dplyr::mutate(gap = mean_arith - mean_comp,      # between the two annual figures
                half_var = vol^2 / 2) |>           # the drag of chapter 3, per year
  dplyr::arrange(dplyr::desc(mean_comp))
stopifnot(all(moments$gap > 0), all(moments$gap < moments$half_var))

vol_spread <- max(moments$vol) / min(moments$vol)
mean_cor   <- mean(stats::cor(R)[upper.tri(stats::cor(R))])
c(vol_spread = vol_spread, mean_correlation = mean_cor)

## ---- tbl-09-drag ----
# Where the two definitions of an average return disagree most, with half the
# annual variance beside the gap. The gap is the price of volatility rather
# than a rounding artifact, and it falls short of half the variance because
# twelve compounded months add return on return.
moments |>
  dplyr::slice_max(gap, n = 4) |>
  dplyr::mutate(dplyr::across(c(mean_arith, mean_comp, vol, gap, half_var),
                              ~ sprintf("%.2f%%", 100 * .x))) |>
  kable(align = "lrrrrr",
        col.names = c("", "arithmetic", "compounded", "volatility", "gap",
                      "half the variance"))

## ---- dominance ----
# j dominates i if it has a weakly higher mean and a weakly lower volatility.
# A sample statement with no test attached: it says what happened, not what
# will happen.
dominated <- vapply(seq_len(nrow(moments)), function(i) {
  any(moments$mean_comp >= moments$mean_comp[i] &
      moments$vol       <= moments$vol[i] &
      seq_len(nrow(moments)) != i)
}, logical(1))

moments$asset[dominated]

## ---- dominance-count ----
n_dominating <- function(i) sum(moments$mean_comp >= moments$mean_comp[i] &
                                moments$vol       <= moments$vol[i]) - 1L
by_how_many <- setNames(vapply(seq_len(nrow(moments)), n_dominating, integer(1)),
                        moments$asset)
sort(by_how_many[by_how_many > 0], decreasing = TRUE)

## ---- fig-09-mu-sigma ----
# The sixteen risky series in the volatility-return plane. Anything with
# another point above and to its left is dominated: less return for more risk,
# over this sample. The efficient assets are the ones with nothing to their
# northwest.
moments |>
  dplyr::mutate(status = ifelse(dominated, "dominated", "on the boundary")) |>
  ggplot2::ggplot(ggplot2::aes(vol, mean_comp, colour = status)) +
  ggplot2::geom_point(size = 2.6) +
  ggplot2::geom_text(ggplot2::aes(label = asset), hjust = -0.11, size = 2.5,
                     show.legend = FALSE) +
  ggplot2::scale_x_continuous(labels = scales::percent,
                              expand = ggplot2::expansion(mult = c(0.05, 0.32))) +
  ggplot2::scale_y_continuous(labels = scales::percent) +
  ggplot2::scale_colour_manual(values = unname(tidyaa_colors[c("broken", "blue")])) +
  ggplot2::labs(x = "annualized volatility", y = "compounded return", colour = NULL)

# ===== Specifying and solving the problem =====

## ---- spec ----
base_spec <- portfolio.spec(assets = colnames(Re)) |>
  add.constraint(type = "full_investment") |>   # weights sum to one
  add.constraint(type = "long_only")            # 0 <= w <= 1

min_var_spec <- base_spec |>
  add.objective(type = "risk", name = "var")

w_gmv <- extractWeights(optimize.portfolio(Re, min_var_spec, optimize_method = "ROI"))
round(w_gmv[w_gmv > 0.005], 4)

## ---- portfolio-stats ----
S <- stats::cov(Re)
mu <- colMeans(Re)
p_vol <- function(w) sqrt(as.numeric(t(w) %*% S %*% w)) * sqrt(12)
p_ret <- function(w) sum(mu * w) * 12
p_sr  <- function(w) p_ret(w) / p_vol(w)

c(volatility = p_vol(w_gmv), excess_return = p_ret(w_gmv), sharpe = p_sr(w_gmv))

# ===== The tangency portfolio =====

## ---- tangency ----
ef_spec <- base_spec |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "StdDev")

ef <- create.EfficientFrontier(Re, ef_spec, type = "mean-StdDev", n.portfolios = 200)

# `ef$frontier` is a matrix carrying a class attribute, and `as.data.frame()`
# dispatches on that class: it returns every cell in a single column rather
# than one row of 19 per frontier portfolio. Strip the class first, or index it
# as the matrix it is.
fr <- as.data.frame(unclass(ef$frontier))
stopifnot(ncol(fr) == ncol(Re) + 3L)

# Returns are already in excess of the bill, so the Sharpe ratio is the ratio
# itself: no risk-free rate to subtract.
fr$sharpe <- fr$mean / fr$StdDev
i_tan <- which.max(fr$sharpe)

wcols <- grep("^w[.]", colnames(fr))
w_tan <- setNames(as.numeric(fr[i_tan, wcols]), sub("^w[.]", "", colnames(fr)[wcols]))
w_tan <- w_tan[colnames(Re)]
round(w_tan[w_tan > 0.005], 4)

## ---- tbl-09-anchors ----
# The two anchor portfolios against two things anybody might hold instead. All
# figures annualized, in excess of the bill.
n <- ncol(Re)
eq_i <- grepl("_equity$", colnames(Re)); bd_i <- grepl("_government$", colnames(Re))
w_6040 <- setNames(rep(0, n), colnames(Re))
w_6040[eq_i] <- 0.6 / sum(eq_i); w_6040[bd_i] <- 0.4 / sum(bd_i)
w_eq <- setNames(rep(1 / n, n), colnames(Re))

tibble::tibble(
  portfolio = c("Minimum variance", "Tangency", "60/40", "Equal weight"),
  vol    = c(p_vol(w_gmv), p_vol(w_tan), p_vol(w_6040), p_vol(w_eq)),
  ret    = c(p_ret(w_gmv), p_ret(w_tan), p_ret(w_6040), p_ret(w_eq)),
  sharpe = c(p_sr(w_gmv),  p_sr(w_tan),  p_sr(w_6040),  p_sr(w_eq)),
  held   = c(sum(w_gmv > 0.005), sum(w_tan > 0.005), sum(w_6040 > 0.005), n)
) |>
  dplyr::mutate(dplyr::across(c(vol, ret), ~ sprintf("%.2f%%", 100 * .x)),
                sharpe = sprintf("%.3f", sharpe)) |>
  kable(align = "lrrrr",
        col.names = c("", "volatility", "excess return", "Sharpe", "positions held"))

## ---- frontier-facts ----
# What the text says about the frontier's holdings, computed and asserted
# rather than typed. `US_credit` has the most negative skewness of the sixteen;
# it enters the frontier at the tangency point and grows to the right of it;
# and between the two ends the largest holdings are `US_equity` and `US_credit`.
skew <- vapply(colnames(R), function(a)
  as.numeric(PerformanceAnalytics::skewness(R[, a])), numeric(1))
peak <- vapply(colnames(Re), function(a) max(fr[[paste0("w.", a)]]), numeric(1))
w_credit   <- fr[["w.US_credit"]]
top_series <- names(which.max(mu))
x_credit   <- as.numeric(R[, "US_credit"])
skew_credit_less_one <- as.numeric(
  PerformanceAnalytics::skewness(x_credit[-which.min(x_credit)]))
stopifnot(
  names(which.min(skew)) == "US_credit",
  w_tan[["US_credit"]] < 0.01,
  all(w_credit[seq_len(i_tan)] <= w_tan[["US_credit"]] + 1e-8),
  peak[["US_credit"]] > 10 * w_tan[["US_credit"]],
  fr[nrow(fr), paste0("w.", top_series)] > 0.999,
  identical(setdiff(names(sort(peak, decreasing = TRUE))[1:4],
                    c("US_government", top_series)),
            c("US_equity", "US_credit"))
)

# ===== Worked: the closed form of @eq-09-gmv against the solver =====

## ---- closed-form-gmv ----
iota <- rep(1, ncol(Re))
Sinv <- solve(S)

A <- as.numeric(t(iota) %*% Sinv %*% iota)
B <- as.numeric(t(iota) %*% Sinv %*% mu)
C <- as.numeric(t(mu)   %*% Sinv %*% mu)

w_gmv_cf <- setNames(as.numeric(Sinv %*% iota) / A, colnames(Re))
w_tan_cf <- setNames(as.numeric(Sinv %*% mu)   / B, colnames(Re))

round(sort(w_gmv_cf)[1:4], 4)      # the four most negative

## ---- closed-form-compare ----
tibble::tibble(
  quantity = c("portfolio volatility, annualized",
               "positions held",
               "most negative weight",
               "sum of weights"),
  closed_form = c(sprintf("%.2f%%", 100 * sqrt(1 / A) * sqrt(12)),
                  sprintf("%d", sum(abs(w_gmv_cf) > 0.005)),
                  sprintf("%.1f%%", 100 * min(w_gmv_cf)),
                  sprintf("%.4f", sum(w_gmv_cf))),
  long_only   = c(sprintf("%.2f%%", 100 * p_vol(w_gmv)),
                  sprintf("%d", sum(w_gmv > 0.005)),
                  sprintf("%.1f%%", 100 * min(w_gmv)),
                  sprintf("%.4f", sum(w_gmv)))
) |>
  kable(align = "lrr", col.names = c("", "@eq-09-gmv", "ROI, long only"))

## ---- closed-form-identities ----
c(gmv_variance_from_A   = 1 / A,
  gmv_variance_measured = as.numeric(t(w_gmv_cf) %*% S %*% w_gmv_cf),
  max_sharpe_sqrt_C     = sqrt(C),
  max_sharpe_long_only  = p_sr(w_tan) / sqrt(12))

# ===== The solver most examples use is the wrong one =====

## ---- cvxr-whitelist ----
pa_cvxr_solvers <- c("CBC", "GLPK", "GLPK_MI", "OSQP", "CPLEX",
                     "SCS", "ECOS", "GUROBI", "MOSEK")
setdiff(CVXR::installed_solvers(), pa_cvxr_solvers)

## ---- silent-failure ----
opt_bad <- optimize.portfolio(Re, min_var_spec,
                              optimize_method = c("CVXR", "CLARABEL"))
c(class = class(opt_bad)[1],
  has_weights = !is.null(extractWeights(opt_bad)),
  elapsed = unname(opt_bad$elapsed_time))

## ---- solve-checked ----
solve_checked <- function(R, spec, ...) {
  out <- optimize.portfolio(R, spec, ...)
  w <- extractWeights(out)
  if (is.null(w) || anyNA(w)) {
    cli::cli_abort(c(
      "The solver returned no usable weights.",
      "i" = "optimize.portfolio() returned an object of class {.cls {class(out)[1]}}.",
      ">" = "If you are using CVXR, the second element of {.arg optimize_method}
             must be one of {.val {pa_cvxr_solvers}}."
    ))
  }
  out
}

try(solve_checked(Re, min_var_spec, optimize_method = c("CVXR", "CLARABEL")))

# ===== An exact budget constraint can be reported as infeasible =====

## ---- target-trap ----
target_monthly <- as.numeric(quantile(mu, 0.75))

on_constraint <- base_spec |>
  add.constraint(type = "return", return_target = target_monthly) |>
  add.objective(type = "risk", name = "var")

on_objective <- base_spec |>
  add.objective(type = "return", name = "mean", target = target_monthly) |>
  add.objective(type = "risk", name = "var")

achieved <- function(spec, method) {
  w <- extractWeights(optimize.portfolio(Re, spec, optimize_method = method))
  sum(w * mu)
}

trap <- tibble::tibble(
  route = c("constraint, ROI", "constraint, CVXR/OSQP",
            "objective, ROI",  "objective, CVXR/OSQP"),
  achieved = c(achieved(on_constraint, "ROI"),
               achieved(on_constraint, c("CVXR", "OSQP")),
               achieved(on_objective,  "ROI"),
               achieved(on_objective,  c("CVXR", "OSQP")))
) |>
  dplyr::mutate(target = target_monthly,
                hit = abs(achieved - target) < 1e-8)
trap

# What the fourth route solved instead: the same two objectives with the target
# removed, which is quadratic utility at the default risk aversion of one.
no_target <- base_spec |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk", name = "var")
stopifnot(trap$hit[1:3], !trap$hit[4],
          isTRUE(all.equal(trap$achieved[4], achieved(no_target, "ROI"),
                           tolerance = 1e-6)))

# ===== The package's own frontier chart =====

## ---- fig-09-native-frontier ----
# The package's own frontier chart. Base graphics, unstyled, and the whole
# picture in one line.
chart.EfficientFrontier(ef, match.col = "StdDev", tangent.line = TRUE, rf = 0,
                        main = "", RAR.text = "Sharpe")

# ===== The frontier is a set of answers, not an object =====

## ---- utility-portfolios ----
# Quadratic utility: maximize mu'w - lambda * w'Sigma w. In PortfolioAnalytics
# this is a return objective plus a risk objective carrying `risk_aversion`.
# Note that `risk_aversion` is gamma/2, not gamma -- see appendix B.
qu_weights <- function(lambda) {
  spec <- base_spec |>
    add.objective(type = "return", name = "mean") |>
    add.objective(type = "risk",   name = "var", risk_aversion = lambda)
  w <- extractWeights(optimize.portfolio(Re, spec, optimize_method = "ROI"))
  w[colnames(Re)]
}

lambdas <- c(1, 2, 5, 10, 25)
w_qu <- lapply(lambdas, qu_weights)
names(w_qu) <- sprintf("lambda = %g", lambdas)

vapply(w_qu, function(w) c(vol = p_vol(w), ret = p_ret(w)), numeric(2)) |> round(4)

## ---- allocation-line ----
# The capital allocation line. Returns here are already in excess of the bill,
# so the risk-free asset sits at the origin and a mix of a in the tangency
# portfolio and 1-a in the bill is simply a scalar multiple of it.
a <- seq(0, 1.6, by = 0.2)
cal <- tibble::tibble(
  label = sprintf("%.0f%% risky", 100 * a),
  vol   = a * p_vol(w_tan),
  ret   = a * p_ret(w_tan),
  kind  = "capital allocation line"
)

## ---- frontier-points ----
# one row per asset, built by name so a volatility can never be paired with
# another asset's return
assets <- moments |>
  dplyr::mutate(vol_m = vol, ret_m = (apply(R, 2, mean) * 12)[asset])

named <- function(label, w, kind) {
  tibble::tibble(label = label, vol = p_vol(w), ret = p_ret(w), kind = kind)
}

pts <- dplyr::bind_rows(
  assets |> dplyr::transmute(label = asset, vol = vol_m, ret = ret_m,
                             kind = "asset"),
  named("minimum variance", w_gmv, "anchor"),
  named("tangency",         w_tan, "anchor"),
  named("equal weight",     w_eq,  "reference"),
  named("60/40",            w_6040, "reference"),
  dplyr::bind_rows(Map(named, names(w_qu), w_qu, "quadratic utility")),
  cal
)

dplyr::count(pts, kind)

## ---- fig-09-frontier ----
# The whole picture, drawn from a single data frame. The hyperbola is the
# long-only frontier; the straight line from the origin is the capital
# allocation line, which in excess-return space starts at zero. Diamonds are
# quadratic-utility solutions at five risk aversions and they sit on the
# frontier, as they must.
lab <- pts |> dplyr::filter(kind %in% c("anchor", "reference", "quadratic utility"))

ggplot2::ggplot() +
  ggplot2::geom_line(data = dplyr::filter(pts, kind == "capital allocation line"),
                     ggplot2::aes(vol, ret), linetype = "22",
                     colour = tidyaa_colors[["ink_soft"]], linewidth = 0.45) +
  ggplot2::geom_point(data = dplyr::filter(pts, kind == "capital allocation line"),
                      ggplot2::aes(vol, ret), size = 1.1,
                      colour = tidyaa_colors[["ink_soft"]]) +
  ggplot2::geom_line(data = fr, ggplot2::aes(StdDev * sqrt(12), mean * 12),
                     colour = tidyaa_colors[["ink"]], linewidth = 0.8) +
  ggplot2::geom_point(data = dplyr::filter(pts, kind == "asset"),
                      ggplot2::aes(vol, ret), size = 1.8,
                      colour = tidyaa_colors[["rule"]]) +
  ggplot2::geom_text(data = dplyr::filter(pts, kind == "asset"),
                     ggplot2::aes(vol, ret, label = label), size = 2,
                     hjust = -0.12, colour = tidyaa_colors[["ink_soft"]]) +
  ggplot2::geom_point(data = dplyr::filter(pts, kind == "quadratic utility"),
                      ggplot2::aes(vol, ret), shape = 23, size = 2.4,
                      fill = tidyaa_colors[["caution"]],
                      colour = tidyaa_colors[["ink"]]) +
  ggplot2::geom_point(data = dplyr::filter(pts, kind == "reference"),
                      ggplot2::aes(vol, ret), shape = 22, size = 2.6,
                      fill = tidyaa_colors[["good"]],
                      colour = tidyaa_colors[["ink"]]) +
  ggplot2::geom_point(data = dplyr::filter(pts, kind == "anchor"),
                      ggplot2::aes(vol, ret), shape = 21, size = 3.6,
                      fill = tidyaa_colors[["blue_lit"]],
                      colour = tidyaa_colors[["ink"]]) +
  ggplot2::geom_text(data = lab, ggplot2::aes(vol, ret, label = label),
                     size = 2.5, hjust = -0.14, vjust = 1.6) +
  ggplot2::scale_x_continuous(labels = scales::percent,
                              expand = ggplot2::expansion(mult = c(0.04, 0.26))) +
  ggplot2::scale_y_continuous(labels = scales::percent) +
  ggplot2::labs(x = "annualized volatility", y = "annualized excess return")

# ===== Worked: the same five portfolios, four different ways of asking =====

## ---- equivalences ----
best_frontier <- function(target_vol) {
  i <- which.min(abs(fr$StdDev * sqrt(12) - target_vol))
  w <- setNames(as.numeric(fr[i, wcols]), sub("^w[.]", "", colnames(fr)[wcols]))
  w[colnames(Re)]
}

tibble::tibble(
  portfolio = names(w_qu),
  qu_vol    = vapply(w_qu, p_vol, numeric(1)),
  qu_ret    = vapply(w_qu, p_ret, numeric(1)),
  frontier_ret_at_same_vol =
    vapply(w_qu, function(w) p_ret(best_frontier(p_vol(w))), numeric(1))
) |>
  dplyr::mutate(gap = qu_ret - frontier_ret_at_same_vol) |>
  dplyr::mutate(dplyr::across(-portfolio, ~ sprintf("%.4f", .x))) |>
  kable(align = "lrrrr",
        col.names = c("", "volatility", "return", "frontier return at that risk",
                      "gap"))

# ===== Reading the frontier through its weights =====

## ---- fig-09-ef-weights ----
# Weights along the efficient frontier. Each vertical slice is one portfolio;
# the left edge is minimum variance and the right edge is the highest
# attainable return. The two dashed lines mark the minimum-variance and
# tangency portfolios.
wlong <- as.data.frame(fr[, wcols])
colnames(wlong) <- sub("^w[.]", "", colnames(wlong))
wlong$vol <- fr$StdDev * sqrt(12)

wlong |>
  tidyr::pivot_longer(-vol, names_to = "series", values_to = "weight") |>
  dplyr::mutate(kind = dplyr::case_when(
    grepl("_equity$", series)     ~ "equity",
    grepl("_credit$", series)     ~ "credit",
    grepl("_government$", series) ~ "government",
    TRUE                          ~ "commodity")) |>
  ggplot2::ggplot(ggplot2::aes(vol, weight, fill = series)) +
  ggplot2::geom_area(colour = "white", linewidth = 0.08) +
  ggplot2::geom_vline(xintercept = p_vol(w_gmv), linetype = "22",
                      linewidth = 0.4, colour = tidyaa_colors[["ink"]]) +
  ggplot2::geom_vline(xintercept = p_vol(w_tan), linetype = "22",
                      linewidth = 0.4, colour = tidyaa_colors[["ink"]]) +
  ggplot2::scale_x_continuous(labels = scales::percent) +
  ggplot2::scale_y_continuous(labels = scales::percent) +
  ggplot2::labs(x = "annualized volatility of the frontier portfolio",
                y = "weight", fill = NULL) +
  ggplot2::theme(legend.position = "right",
                 legend.key.size = ggplot2::unit(0.32, "cm"),
                 legend.text = ggplot2::element_text(size = 6.5))

## ---- frontier-corner ----
corner <- fr[nrow(fr), wcols]
names(corner) <- sub("^w[.]", "", colnames(fr)[wcols])
round(sort(unlist(corner), decreasing = TRUE)[1:3], 4)

