# ===== Worked: where each asset enters and leaves =====

## ---- entry-exit ----
held <- vapply(colnames(Re), function(a) {
  w <- fr[[paste0("w.", a)]]
  v <- fr$StdDev * sqrt(12)
  if (all(w <= 0.005)) return(c(from = NA, to = NA, peak = 0))
  c(from = min(v[w > 0.005]), to = max(v[w > 0.005]), peak = max(w))
}, numeric(3))

t(held) |>
  as.data.frame() |>
  tibble::rownames_to_column("series") |>
  dplyr::arrange(from) |>
  dplyr::mutate(dplyr::across(c(from, to), ~ sprintf("%.1f%%", 100 * .x)),
                peak = sprintf("%.0f%%", 100 * peak)) |>
  kable(align = "lrrr",
        col.names = c("", "first held at vol", "last held at vol", "peak weight"))

# ===== The left end is stable and the right end is not =====

## ---- bootstrap ----
set.seed(1602)

block_index <- function(n, block = 12L) {
  starts <- sample.int(n - block + 1L, ceiling(n / block), replace = TRUE)
  as.vector(outer(0:(block - 1L), starts, "+"))[seq_len(n)]
}

# Half the L1 distance between two long-only weight vectors: the share of the
# portfolio that must change hands to get from one to the other. The guard is
# not decoration -- given NULL, the unguarded arithmetic returns zero, and a
# failed solve would enter the sample as a portfolio that did not move.
turnover <- function(w1, w2) {
  if (is.null(w1) || is.null(w2)) stop("a failed solve is not a turnover of zero")
  sum(abs(w1[names(w2)] - w2)) / 2
}

B <- 200L
boot <- vapply(seq_len(B), function(b) {
  Rb <- xts::xts(zoo::coredata(Re)[block_index(nrow(Re)), ], order.by = zoo::index(Re))
  wg <- extractWeights(solve_checked(Rb, min_var_spec, optimize_method = "ROI"))
  fb <- as.data.frame(unclass(
    create.EfficientFrontier(Rb, ef_spec, type = "mean-StdDev",
                             n.portfolios = 60)$frontier))
  wt <- setNames(as.numeric(fb[which.max(fb$mean / fb$StdDev), wcols]),
                 sub("^w[.]", "", colnames(fb)[wcols]))
  c(gmv = turnover(wg[colnames(Re)], w_gmv),
    tangency = turnover(wt[colnames(Re)], w_tan))
}, numeric(2))

## ---- tbl-09-bootstrap ----
# How far each portfolio moves when the sample is resampled. Turnover is the
# share of the portfolio that must be traded to reach the resampled answer
# from the full-sample one.
tibble::tibble(
  portfolio = c("Minimum variance", "Tangency"),
  mean   = c(mean(boot["gmv", ]), mean(boot["tangency", ])),
  median = c(median(boot["gmv", ]), median(boot["tangency", ])),
  p95    = c(quantile(boot["gmv", ], .95), quantile(boot["tangency", ], .95))
) |>
  dplyr::mutate(dplyr::across(where(is.numeric), ~ sprintf("%.3f", .x))) |>
  kable(align = "lrrr", col.names = c("", "mean", "median", "95th percentile"))

# ===== Diversification effort and diversification payoff are unrelated =====

## ---- diversification ----
Req <- Re[, grepl("_equity$", colnames(Re))]
Ceq <- stats::cor(Req)
Seq <- stats::cov(Req)

w_gmv_eq <- extractWeights(optimize.portfolio(Req,
  portfolio.spec(colnames(Req)) |>
    add.constraint("full_investment") |> add.constraint("long_only") |>
    add.objective(type = "risk", name = "var"),
  optimize_method = "ROI"))

# Effective bets: the reciprocal of the Herfindahl index of the weights. Sixteen
# equal positions score 16, everything in one name scores 1. It counts positions
# the way an investor would, not the way the weight vector's length does.
eff_bets <- function(w) 1 / sum(w^2)

vol_eq <- sqrt(as.numeric(t(w_gmv_eq) %*% Seq %*% w_gmv_eq)) * sqrt(12)

# The comparison the text draws, asserted: the equity portfolio holds more
# effective positions and lands no further below its least volatile constituent.
stopifnot(eff_bets(w_gmv_eq) > eff_bets(w_gmv),
          vol_eq / min(apply(Req, 2, ann_vol)) > p_vol(w_gmv) / min(moments$vol))

tibble::tibble(
  universe         = c("16 mixed classes", "5 equity classes"),
  mean_correlation = c(mean_cor, mean(Ceq[upper.tri(Ceq)])),
  gmv_vol          = c(p_vol(w_gmv), vol_eq),
  lowest_vol_asset = c(min(moments$vol), min(apply(Req, 2, ann_vol))),
  effective_bets   = c(eff_bets(w_gmv), eff_bets(w_gmv_eq))
) |>
  dplyr::mutate(gain = gmv_vol / lowest_vol_asset - 1)

## ---- fig-09-two-frontiers ----
# The same construction on two universes. The equity frontier is not a smaller
# version of the mixed one; it is its top-right stub, because both end in the
# same asset.
ef_eq <- create.EfficientFrontier(Req,
  portfolio.spec(colnames(Req)) |>
    add.constraint("full_investment") |> add.constraint("long_only") |>
    add.objective(type = "return", name = "mean") |>
    add.objective(type = "risk",   name = "StdDev"),
  type = "mean-StdDev", n.portfolios = 200)

fr_eq <- as.data.frame(unclass(ef_eq$frontier))

# The text below says both frontiers end in the same asset, an equity market.
end_of <- function(f) {
  w <- unlist(f[nrow(f), grep("^w[.]", colnames(f))])
  sub("^w[.]", "", names(w)[w > 0.99])
}
stopifnot(length(end_of(fr)) == 1L, identical(end_of(fr_eq), end_of(fr)),
          grepl("_equity$", end_of(fr)))

both <- rbind(
  data.frame(vol = fr$StdDev * sqrt(12),    ret = fr$mean * 12,
             universe = "16 mixed classes"),
  data.frame(vol = fr_eq$StdDev * sqrt(12), ret = fr_eq$mean * 12,
             universe = "5 equity classes")
)

ggplot2::ggplot(both, ggplot2::aes(vol, ret, colour = universe)) +
  ggplot2::geom_line(linewidth = 0.9) +
  ggplot2::geom_point(data = moments |>
                        dplyr::mutate(ret = (apply(R, 2, mean) * 12)[asset],
                                      universe = "16 mixed classes"),
                      ggplot2::aes(vol, ret), size = 1.7, show.legend = FALSE,
                      colour = tidyaa_colors[["ink_soft"]]) +
  ggplot2::scale_colour_manual(values = unname(tidyaa_colors[c("ink", "caution")]),
                               name = NULL) +
  ggplot2::scale_x_continuous(labels = scales::percent) +
  ggplot2::scale_y_continuous(labels = scales::percent) +
  ggplot2::theme(legend.position = "top") +
  ggplot2::labs(x = "annualized volatility", y = "annualized excess return")

# ===== Five hundred universes, one constant =====

## ---- subuniverses ----
set.seed(1602)

gmv_vol_of <- function(X) {
  w <- extractWeights(optimize.portfolio(X,
    portfolio.spec(colnames(X)) |>
      add.constraint("full_investment") |> add.constraint("long_only") |>
      add.objective(type = "risk", name = "var"),
    optimize_method = "ROI"))
  sqrt(as.numeric(t(w) %*% stats::cov(X) %*% w)) * sqrt(12)
}

draws <- lapply(3:16, function(n) {
  lapply(seq_len(if (n == 16) 1 else 40), function(...) {
    X <- Re[, sort(sample.int(ncol(Re), n))]
    C <- stats::cor(X)
    data.frame(n = n, mean_cor = mean(C[upper.tri(C)]),
               gmv_vol = gmv_vol_of(X), min_vol = min(apply(X, 2, ann_vol)))
  })
})
subu <- do.call(rbind, unlist(draws, recursive = FALSE)) |>
  dplyr::mutate(gain = gmv_vol / min_vol - 1)

c(universes = nrow(subu),
  median_gain = median(subu$gain),
  worst_gain = min(subu$gain),
  best_gain = max(subu$gain))

## ---- what-explains-it ----
r2 <- function(f) summary(stats::lm(f, data = subu))$r.squared

c(lowest_vol_alone    = r2(log(gmv_vol) ~ log(min_vol)),
  correlation_alone    = r2(log(gmv_vol) ~ mean_cor),
  everything           = r2(log(gmv_vol) ~ log(min_vol) + mean_cor + n))

# ===== What each constraint costs =====

## ---- constraint-ladder ----
group_of <- function(a) dplyr::case_when(
  grepl("_equity$", a)     ~ "equity",
  grepl("_government$", a) ~ "government",
  grepl("_credit$", a)     ~ "credit",
  TRUE                     ~ "commodity")
# split() returns its groups in alphabetical order, so the limit vectors below
# are built by name rather than positionally. Getting that wrong applies the
# equity limit to the commodity and nothing complains.
grp <- split(seq_len(ncol(Re)), group_of(colnames(Re)))
gmin <- c(commodity = 0.00, credit = 0.05, equity = 0.20, government = 0.10)
gmax <- c(commodity = 0.15, credit = 0.40, equity = 0.60, government = 0.50)
stopifnot(identical(names(grp), names(gmin)))

spec_unconstrained <- portfolio.spec(colnames(Re)) |>
  add.constraint(type = "full_investment") |>
  add.constraint(type = "box", min = -1, max = 1) |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "StdDev")

spec_box <- base_spec |>
  add.constraint(type = "box", min = 0, max = 0.25) |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "StdDev")

spec_group <- base_spec |>
  add.constraint(type = "box", min = 0, max = 0.25) |>
  add.constraint(type = "group", groups = grp,
                 group_min = unname(gmin[names(grp)]),
                 group_max = unname(gmax[names(grp)])) |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "StdDev")

ladder <- list(`1 no short-sale limit` = spec_unconstrained,
               `2 long only`           = ef_spec,
               `3 plus a 25% cap`      = spec_box,
               `4 plus group limits`   = spec_group)

fronts <- lapply(names(ladder), function(nm) {
  e <- create.EfficientFrontier(Re, ladder[[nm]], type = "mean-StdDev",
                                n.portfolios = 100)
  f <- as.data.frame(unclass(e$frontier))
  data.frame(spec = nm, vol = f$StdDev * sqrt(12), ret = f$mean * 12,
             sharpe = f$mean / f$StdDev)
}) |> dplyr::bind_rows()

## ---- tbl-09-ladder ----
# The same optimization under four constraint sets. Each row adds a
# restriction to the one above it.
ladder_tab <- fronts |>
  dplyr::group_by(spec) |>
  dplyr::summarise(min_vol = min(vol), max_ret = max(ret),
                   best_sharpe = max(sharpe) * sqrt(12), .groups = "drop")

# Each rung only adds a restriction, so no row can be better than the one above
# it. The rows are read by position in the text below, hence the first check.
stopifnot(identical(ladder_tab$spec, names(ladder)),
          !is.unsorted(ladder_tab$min_vol),
          !is.unsorted(rev(ladder_tab$max_ret)),
          !is.unsorted(rev(round(ladder_tab$best_sharpe, 3))))
rung <- function(i, what) ladder_tab[[what]][i]

# Two facts the text below leans on: under a 25% cap the highest-return
# portfolio is four series at the cap, all of them equity markets, and the
# group limits leave the best Sharpe ratio of the capped frontier where it was.
top4 <- names(sort(mu, decreasing = TRUE))[1:4]
stopifnot(all(grepl("_equity$", top4)),
          abs(rung(4, "best_sharpe") - rung(3, "best_sharpe")) < 5e-4)

ladder_tab |>
  dplyr::mutate(dplyr::across(c(min_vol, max_ret), ~ sprintf("%.2f%%", 100 * .x)),
                best_sharpe = sprintf("%.3f", best_sharpe)) |>
  kable(align = "lrrr",
        col.names = c("", "lowest volatility reachable", "highest return reachable",
                      "best Sharpe on the frontier"))

## ---- fig-09-ladder ----
# Four frontiers, each a subset of the one above it. Every constraint moves
# the attainable set south-east, and the gray points are the individual series
# for scale.
ggplot2::ggplot() +
  ggplot2::geom_point(data = assets, ggplot2::aes(vol_m, ret_m),
                      colour = tidyaa_colors[["rule"]], size = 1.8) +
  ggplot2::geom_text(data = assets, ggplot2::aes(vol_m, ret_m, label = asset),
                     size = 2, hjust = -0.1, colour = tidyaa_colors[["ink_soft"]]) +
  ggplot2::geom_line(data = fronts, ggplot2::aes(vol, ret, colour = spec),
                     linewidth = 0.8) +
  ggplot2::scale_x_continuous(labels = scales::percent,
                              expand = ggplot2::expansion(mult = c(0.05, 0.25))) +
  ggplot2::scale_y_continuous(labels = scales::percent) +
  ggplot2::scale_colour_manual(values = unname(tidyaa_colors[c("ink", "blue",
                                                               "caution", "broken")]),
                               name = NULL) +
  ggplot2::theme(legend.position = "top") +
  ggplot2::labs(x = "annualized volatility", y = "annualized excess return")

# ===== And it does not survive contact with the future =====

## ---- tbl-09-oos ----
# The same three portfolios, estimated on the full sample and estimated on a
# sixty-month rolling window. Only the second column is achievable.
oos <- utils::read.csv("tables/oos-sweep.csv") |>
  dplyr::filter(universe == "classes", window == 60,
                frequency == "months", basis == "gross")
sr_oos <- function(s) oos$sharpe[match(s, oos$strategy)]

tibble::tibble(
  portfolio       = c("Tangency", "Minimum variance", "Equal weight"),
  in_sample       = c(p_sr(w_tan), p_sr(w_gmv), p_sr(w_eq)),
  out_of_sample   = sr_oos(c("max_sharpe", "min_variance", "equal_weight"))
) |>
  dplyr::mutate(kept = out_of_sample / in_sample) |>
  knitr::kable(digits = 3)

## ---- oos-ranking ----
three    <- c("max_sharpe", "min_variance", "equal_weight")
promised <- c(max_sharpe = p_sr(w_tan), min_variance = p_sr(w_gmv),
              equal_weight = p_sr(w_eq))
kept     <- setNames(sr_oos(three) / promised[three], three)

# The register in full for the sixteen classes, gross of costs: three estimation
# windows by three rebalancing frequencies, every cell out of sample from
# observation 121.
cells <- utils::read.csv("tables/oos-sweep.csv") |>
  dplyr::filter(universe == "classes", basis == "gross") |>
  dplyr::group_by(window, frequency) |>
  dplyr::summarise(tangency     = sharpe[strategy == "max_sharpe"],
                   min_variance = sharpe[strategy == "min_variance"],
                   equal_weight = sharpe[strategy == "equal_weight"],
                   lowest       = strategy[which.min(sharpe)],
                   n_strategies = dplyr::n(),
                   .groups = "drop") |>
  dplyr::mutate(tan_kept = tangency     / promised[["max_sharpe"]],
                mv_kept  = min_variance / promised[["min_variance"]],
                ew_kept  = equal_weight / promised[["equal_weight"]])
stopifnot(nrow(cells) == 9L, setequal(cells$window, c(36, 60, 120)))

# In sample the tangency portfolio is first, by construction.
stopifnot(names(which.max(promised)) == "max_sharpe")

# What holds in every cell of the register: minimum variance has the highest
# Sharpe ratio of the three, and the tangency portfolio keeps the smallest share
# of the Sharpe ratio it promised.
stopifnot(all(cells$min_variance > pmax(cells$tangency, cells$equal_weight)),
          all(cells$tan_kept < pmin(cells$mv_kept, cells$ew_kept)))

# What holds at the two shorter windows and not at 120 months: the tangency
# portfolio is last of the three. In the cell the table above shows it is last
# of all the strategies in the register, and the other two keep what they
# promised.
short <- cells[cells$window < 120, ]
long  <- cells[cells$window == 120, ]
at60  <- cells[cells$window == 60  & cells$frequency == "months", ]
at120 <- cells[cells$window == 120 & cells$frequency == "months", ]
stopifnot(all(short$tangency < short$equal_weight),
          all(long$tangency  > long$equal_weight),
          at60$lowest == "max_sharpe",
          all(kept[c("min_variance", "equal_weight")] > 1))

oos_start <- zoo::index(R)[121]    # the first out-of-sample month of the register
